+     */
+    public String getError() {
+        String message = getMessage();
+        int index = message.indexOf(':');
+        if (index != -1) {
+            int length = message.length();
+            while (index + 1 < length) {
+                if (message.charAt(index + 1) == ' ') {
+                    index++;
+                } else {
+                    break;
+                }
+            }
+            return message.substring(index + 1);
+        }
+        return message;
+    }
